    queue([])

    render(<App />)

    const list = await screen.findByRole('region', { name: 'Work queue' })
    expect(within(list).getByText('Nothing to triage yet.')).toBeTruthy()
    expect(within(list).queryAllByRole('group')).toHaveLength(0)
